-- FE科目B対応オリジナル実戦ケース26件（アルゴリズム22件、セキュリティ4件）。
-- 2023年以降の公開公式過去問を転載したものではありません。
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-001','exam-fe','配列の累積和','アルゴリズム・配列','intermediate','整数配列a=[2,5,1,4]について、s=0から始め、iを0から3まで1ずつ増やし、毎回s=s+a[i]を実行する。','終了時のsは幾つか。','[{"id":"a","text":"10"},{"id":"b","text":"11"},{"id":"c","text":"12"},{"id":"d","text":"14"}]','c','{"a":0,"b":0,"c":100,"d":0}','2+5+1+4=12。ループの範囲を確認し、すべての要素を一度ずつ加算する。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-002','exam-fe','最大値の更新','アルゴリズム・配列','standard','配列a=[3,9,2,7]に対しm=a[0]から始め、i=1,2,3の順にa[i]>mならmをa[i]に更新する。','終了時のmは幾つか。','[{"id":"a","text":"2"},{"id":"b","text":"3"},{"id":"c","text":"7"},{"id":"d","text":"9"}]','d','{"a":0,"b":0,"c":0,"d":100}','配列の各値と現在の最大値mを比較して更新するため最終的に9が残る。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-003','exam-fe','添字の境界','アルゴリズム・配列','standard','要素数n=5の配列aを、添字0からn-1までで処理する。','すべての要素を1回ずつ参照し、範囲外アクセスしないループ条件はどれか。','[{"id":"a","text":"i<=n（iを0から）"},{"id":"b","text":"i<n（iを0から）"},{"id":"c","text":"i<n-1（iを0から）"},{"id":"d","text":"i>=0（iを0から増加）"}]','b','{"a":0,"b":100,"c":0,"d":0}','0始まりのn要素の有効添字は0～n-1。i<nで5回実行し、i=nは参照しない。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-004','exam-fe','二分探索の次の範囲','アルゴリズム・探索','intermediate','昇順配列[2,4,6,8,10,12,14]で10を探す。初期low=0、high=6、mid=floor((low+high)/2)=3とする。','a[mid]=8が10より小さいときの次のlowはどれか。','[{"id":"a","text":"0"},{"id":"b","text":"2"},{"id":"c","text":"3"},{"id":"d","text":"4"}]','d','{"a":0,"b":0,"c":0,"d":100}','配列が昇順なので8以下の前半は探索対象外となり、low=mid+1=4とする。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-005','exam-fe','線形探索の終了','アルゴリズム・探索','standard','配列[4,7,9,11]を先頭から線形探索し、値9を見つけた時点で停止する。','比較した要素数は幾つか。','[{"id":"a","text":"2"},{"id":"b","text":"3"},{"id":"c","text":"4"},{"id":"d","text":"5"}]','b','{"a":0,"b":100,"c":0,"d":0}','4→7→9の順に比較し、3回目で発見して終了する。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-006','exam-fe','文字列の出現回数','アルゴリズム・文字列','standard','文字列s=''ABABA''で、1文字ずつ走査し文字''A''に一致した回数を数える。','結果は幾つか。','[{"id":"a","text":"2"},{"id":"b","text":"3"},{"id":"c","text":"4"},{"id":"d","text":"5"}]','b','{"a":0,"b":100,"c":0,"d":0}','位置0,2,4の3か所が''A''。重なりのある部分文字列ではなく文字単位の比較である。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-007','exam-fe','回文判定の比較','アルゴリズム・文字列','intermediate','文字列''LEVEL''が回文かを調べる。左右の文字を両端から対応づけて比較する。','長さ5の文字列で判定に必要な文字対の比較回数は最大幾つか。','[{"id":"a","text":"1"},{"id":"b","text":"2"},{"id":"c","text":"3"},{"id":"d","text":"5"}]','b','{"a":0,"b":100,"c":0,"d":0}','中央文字を除いた左右2組を比較する。一般に長さnではfloor(n/2)回の比較。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-008','exam-fe','スタックの操作','アルゴリズム・スタック','standard','空のスタックに1,2,3を順にpushし、1回popした後4をpushする。','最後にpopすると得られる値はどれか。','[{"id":"a","text":"1"},{"id":"b","text":"2"},{"id":"c","text":"3"},{"id":"d","text":"4"}]','d','{"a":0,"b":0,"c":0,"d":100}','LIFOなので3を取り出した後に4を積む。次に取り出すのは4。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-009','exam-fe','キューの操作','アルゴリズム・キュー','standard','空のキューにA、B、Cをenqueueし、1回dequeueしてからDをenqueueする。','次にdequeueされる要素はどれか。','[{"id":"a","text":"A"},{"id":"b","text":"B"},{"id":"c","text":"C"},{"id":"d","text":"D"}]','b','{"a":0,"b":100,"c":0,"d":0}','FIFOで最初のAは取り出し済み。残りB、C、Dの先頭Bが次となる。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-010','exam-fe','バブルソートの1周','アルゴリズム・ソート','intermediate','配列[5,1,4,2]に対し左から隣接要素を比較し、大きい方を右へ交換する処理を右端まで1周行う。','1周後の配列はどれか。','[{"id":"a","text":"[1,4,2,5]"},{"id":"b","text":"[1,2,4,5]"},{"id":"c","text":"[5,4,2,1]"},{"id":"d","text":"[1,5,4,2]"}]','a','{"a":100,"b":0,"c":0,"d":0}','5と1を交換→[1,5,4,2]、5と4を交換→[1,4,5,2]、5と2を交換→[1,4,2,5]。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-011','exam-fe','再帰関数の計算','アルゴリズム・再帰','standard','f(0)=0、f(n)=n+f(n-1)（n>0）とする。','f(4)の値は幾つか。','[{"id":"a","text":"6"},{"id":"b","text":"10"},{"id":"c","text":"12"},{"id":"d","text":"24"}]','b','{"a":0,"b":100,"c":0,"d":0}','f(4)=4+3+2+1+0=10。基底条件f(0)=0に達して再帰が終了する。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-012','exam-fe','フィボナッチ数','アルゴリズム・再帰','standard','f(0)=0、f(1)=1、f(n)=f(n-1)+f(n-2)（n>=2）とする。','f(6)はいくつか。','[{"id":"a","text":"5"},{"id":"b","text":"8"},{"id":"c","text":"13"},{"id":"d","text":"21"}]','b','{"a":0,"b":100,"c":0,"d":0}','列は0,1,1,2,3,5,8となるためf(6)=8。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-013','exam-fe','ビット演算AND','アルゴリズム・ビット','intermediate','2進数1101と1011を各ビットごとにAND演算する。','結果の2進数はどれか。','[{"id":"a","text":"1111"},{"id":"b","text":"0110"},{"id":"c","text":"1001"},{"id":"d","text":"1100"}]','c','{"a":0,"b":0,"c":100,"d":0}','1 AND 1の位置だけ1になる。1101 AND 1011=1001。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-014','exam-fe','左シフトの意味','アルゴリズム・ビット','standard','符号なしの8ビット整数で、値5を1ビット左に論理シフトし、あふれは発生しない。','結果の10進値は幾つか。','[{"id":"a","text":"2"},{"id":"b","text":"5"},{"id":"c","text":"10"},{"id":"d","text":"20"}]','c','{"a":0,"b":0,"c":100,"d":0}','5(00000101)を1ビット左へシフトすると00001010=10。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-015','exam-fe','単方向リストの挿入','アルゴリズム・連結リスト','standard','単方向連結リストA→Cがあり、ノードBをAとCの間に挿入する。','リンクを正しくつなぐ手順はどれか。','[{"id":"a","text":"B.next=Cの後、A.next=B"},{"id":"b","text":"A.next=NULLにしてからBを削除"},{"id":"c","text":"C.next=B、A.next=C"},{"id":"d","text":"A.next=CのままB.next=NULL"}]','a','{"a":100,"b":0,"c":0,"d":0}','新ノードBの次をCへ、Aの次をBへ設定してA→B→Cにする。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-016','exam-fe','幅優先探索','アルゴリズム・グラフ','intermediate','グラフで始点Sから辺の本数が最も少ない経路を探す。すべての辺の重みは等しい。','用いる探索法として適切なのはどれか。','[{"id":"a","text":"深さ優先探索のみ"},{"id":"b","text":"幅優先探索"},{"id":"c","text":"常に最大重みを選ぶ貪欲法"},{"id":"d","text":"全頂点を並べ替えるだけの方法"}]','b','{"a":0,"b":100,"c":0,"d":0}','重みなしグラフの最短辺数はBFSで求められる。キューで探索距離が小さい順に訪問する。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-017','exam-fe','最短経路の選択','アルゴリズム・グラフ','standard','非負の辺重みをもつ有向グラフで、始点から全頂点への最短距離を求めたい。','一般的に使われるアルゴリズムはどれか。','[{"id":"a","text":"ダイクストラ法"},{"id":"b","text":"クイックソート"},{"id":"c","text":"二分探索"},{"id":"d","text":"ユークリッドの互除法"}]','a','{"a":100,"b":0,"c":0,"d":0}','負の辺がない重み付きグラフの単一始点最短経路にはダイクストラ法が使える。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-018','exam-fe','階段の上り方','アルゴリズム・動的計画法','standard','1回に1段または2段上れる。段数n=0の上り方を1通りとし、f(n)=f(n-1)+f(n-2)で数える。','4段の階段を上る方法は何通りか。','[{"id":"a","text":"3"},{"id":"b","text":"4"},{"id":"c","text":"5"},{"id":"d","text":"8"}]','c','{"a":0,"b":0,"c":100,"d":0}','f(0)=1、f(1)=1、f(2)=2、f(3)=3、f(4)=5。直前の1段・2段から遷移する。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-019','exam-fe','最小コストの選択','アルゴリズム・動的計画法','intermediate','n=3段の階段で、1回1段又は2段進める。着地時にその段のコストを払い、1段目2、2段目5、3段目1とする。開始地点は0段目。','3段目へ到達する最小コストはどれか。','[{"id":"a","text":"1"},{"id":"b","text":"3"},{"id":"c","text":"6"},{"id":"d","text":"8"}]','b','{"a":0,"b":100,"c":0,"d":0}','0→1→3では2+1=3、0→2→3では5+1=6。よって最小は3。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-020','exam-fe','真偽条件の判定','アルゴリズム・条件分岐','standard','x=7、y=12のとき、条件(x>=5 AND y<10) OR (x=7 AND y=12)を評価する。','条件全体の結果はどれか。','[{"id":"a","text":"真"},{"id":"b","text":"偽"},{"id":"c","text":"未定義"},{"id":"d","text":"xを更新しないと計算できない"}]','a','{"a":100,"b":0,"c":0,"d":0}','前半は真AND偽で偽、後半は真AND真で真。偽OR真は真。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-021','exam-fe','入力値の検証','プログラムの安全性','standard','注文数量を受け取る関数が、数量を整数に変換してから1～100の範囲であるか確認する。入力は文字列''12.5''である。','安全な入力検証として適切なのはどれか。','[{"id":"a","text":"12へ切り捨てて無条件で受理する"},{"id":"b","text":"整数として妥当か確認し、小数を拒否する"},{"id":"c","text":"文字列なら全て受理する"},{"id":"d","text":"100未満なので小数を許可する"}]','b','{"a":0,"b":100,"c":0,"d":0}','整数の注文数量なら小数を黙って切り捨てない。形式・型・範囲を検証して不正な値を拒否する。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-022','exam-fe','重複除去の結果','アルゴリズム・集合','intermediate','配列[2,3,2,5,3]の値を集合に追加し、重複を除く。','集合に含まれる異なる値の個数はどれか。','[{"id":"a","text":"2"},{"id":"b","text":"3"},{"id":"c","text":"4"},{"id":"d","text":"5"}]','b','{"a":0,"b":100,"c":0,"d":0}','異なる要素は2、3、5の3種類。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-023','exam-fe','セッション固定化の防止','セキュリティ実装','standard','Webアプリではログイン前に匿名セッションIDを発行している。攻撃者がこのIDを利用者に使わせる可能性がある。','ログイン成功時に行うべき処理はどれか。','[{"id":"a","text":"同じセッションIDを必ず継続する"},{"id":"b","text":"ログイン成功時にセッションIDを再生成する"},{"id":"c","text":"セッションIDをURLで共有する"},{"id":"d","text":"セッションIDの有効期限をなくす"}]','b','{"a":0,"b":100,"c":0,"d":0}','認証状態の変化時にセッションIDを再生成し、攻撃者が事前固定したIDの流用を防ぐ。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-024','exam-fe','XSSの防止','セキュリティ実装','standard','掲示板に投稿された文字列を、HTMLの本文へ表示する機能がある。ユーザ入力をそのままinnerHTMLへ代入している。','XSSリスクを下げる設計として適切なのはどれか。','[{"id":"a","text":"HTML本文の文脈で適切なエスケープ又は安全なtextContentを使う"},{"id":"b","text":"入力をそのままinnerHTMLへ渡す"},{"id":"c","text":"全画面に管理者権限を付ける"},{"id":"d","text":"エラーログを無効化する"}]','a','{"a":100,"b":0,"c":0,"d":0}','利用者入力をHTMLとして解釈させない。textContentや出力文脈に応じたエスケープが重要。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-025','exam-fe','権限チェックの配置','セキュリティ実装','intermediate','SPAで管理者専用ボタンを非表示にしているが、一般ユーザは開発者ツールでAPIを直接呼び出せる。','必要な追加対策はどれか。','[{"id":"a","text":"ボタンを非表示にするだけでよい"},{"id":"b","text":"APIサーバ側で利用者の権限を検証する"},{"id":"c","text":"JavaScriptを難読化するだけでよい"},{"id":"d","text":"メニューの色を管理者専用にする"}]','b','{"a":0,"b":100,"c":0,"d":0}','クライアントのUI制御は認可ではない。全ての保護対象APIでサーバ側に権限判定が必要。','authored','B');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-b-026','exam-fe','CSRF対策','セキュリティ実装','standard','Cookieでログイン状態を保持するWebアプリが、送金APIに対する他サイトからのリクエストを受け取る可能性がある。','有効なCSRF対策の組合せはどれか。','[{"id":"a","text":"Origin検証やCSRFトークン、適切なSameSite設定を用いる"},{"id":"b","text":"金額を画面から非表示にする"},{"id":"c","text":"APIをGETリクエストに変更する"},{"id":"d","text":"Cookieの有効期限だけ長くする"}]','a','{"a":100,"b":0,"c":0,"d":0}','状態変更APIではOrigin/Referer検証、CSRFトークン、SameSite等を適切に組み合わせる。','authored','B');
